  "paths": {
    "/api/sessions": {
      "post": {
        "operationId": "createSession",
        "tags": [
          "Play"
        ],
        "summary": "Create a game.",
        "description": "You take seat X, and X moves first. The first other player who joins takes seat O. Share the link /?code=<code>. One address can create 60 sessions per hour.\n\nExample:\n\n```sh\ncurl -s -X POST {origin}/api/sessions -H 'X-Player: agent-7f3k9q2m4x8w1z5c' -H 'content-type: application/json' -d '{\"name\":\"Agent match\"}'\n```",
        "parameters": [
          {
            "name": "X-Player",
            "in": "header",
            "required": true,
            "description": "Your player id: 16 to 64 characters from a-z, 0-9 and \"-\". It holds your seat. No account or key.",
            "schema": {
              "type": "string",
              "pattern": "^[a-z0-9-]{16,64}$"
            }
          },
          {
            "$ref": "#/components/parameters/IdempotencyKey"
          }
        ],
        "requestBody": {
          "required": true,
          "content": {
            "application/json": {
              "schema": {
                "$ref": "#/components/schemas/NewSession"
              },
              "example": {
                "name": "Agent match"
              }
            }
          }
        },
        "responses": {
          "201": {
            "description": "The new session.",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/SessionView"
                },
                "example": {
                  "code": "AB3K",
                  "name": "Agent match",
                  "games": [
                    {
                      "moves": [],
                      "times": [],
                      "clock": {
                        "perMove": null,
                        "perGame": null
                      },
                      "timedOut": false
                    }
                  ],
                  "seats": {
                    "X": true,
                    "O": false
                  },
                  "you": "X",
                  "options": {
                    "hideBoard": false,
                    "hideHistory": false,
                    "hideCoordinates": false
                  },
                  "locked": false,
                  "clock": {
                    "perMove": null,
                    "perGame": null
                  },
                  "fixedSeats": false,
                  "watcherChat": true,
                  "flipped": [
                    false
                  ],
                  "now": 1791200000000,
                  "version": 1,
                  "chat": [],
                  "presence": {
                    "X": false,
                    "O": false
                  },
                  "players": {
                    "X": null,
                    "O": null
                  },
                  "names": {
                    "X": "braveOtter",
                    "O": null
                  },
                  "people": {
                    "X": "3f9a0c27d84be615",
                    "O": null
                  },
                  "watchers": [],
                  "youWatcher": null,
                  "seatRequest": null,
                  "turn": "X",
                  "status": {
                    "kind": "playing"
                  },
                  "playoff": null
                }
              }
            }
          },
          "400": {
            "description": "The X-Player header is missing or not 16 to 64 characters from a-z, 0-9 and \"-\", or it starts with \"account-\". Or: The body is not valid JSON, or a field is wrong. Or: The Idempotency-Key header is not valid.",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            }
          },
          "409": {
            "description": "The first request with this Idempotency-Key still runs.",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            }
          },
          "413": {
            "description": "The body is larger than 4 kB.",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            }
          },
          "422": {
            "description": "This Idempotency-Key came with another request before.",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            }
          },
          "429": {
            "description": "This address created 60 sessions in the last hour.",
            "headers": {
              "Retry-After": {
                "description": "Whole seconds to wait before the next try.",
                "schema": {
                  "type": "integer",
                  "minimum": 1
                }
              }
            },
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            }
          }
        }
      }
    },
    "/api/sessions/{code}": {
      "get": {
        "operationId": "getSession",
        "tags": [
          "Play"
        ],
        "summary": "Read a session. With ?wait=<version>, wait for a change first.",
        "description": "Without wait, the answer comes at once. With wait, the server holds the request until the session version is greater than the version you send, or until about 25 s pass. Then it sends the session. Compare the version in the answer to see if something changed. Anybody with the code can read. The X-Player header only sets \"you\".\n\nExample:\n\n```sh\ncurl -s \"{origin}/api/sessions/AB3K?wait=6\" -H 'X-Player: agent-7f3k9q2m4x8w1z5c'\n```",
        "parameters": [
          {
            "name": "code",
            "in": "path",
            "required": true,
            "description": "The session code: 4 letters or digits. Lower case also works.",
            "schema": {
              "type": "string",
              "pattern": "^[ABCDEFGHJKLMNPQRSTUVWXYZ23456789abcdefghjklmnpqrstuvwxyz23456789]{4}$"
            },
            "example": "AB3K"
          },
          {
            "name": "wait",
            "in": "query",
            "description": "A version that you saw. The answer waits until the version is greater.",
            "required": false,
            "schema": {
              "type": "integer",
              "minimum": 0
            },
            "example": "6"
          },
          {
            "name": "X-Player",
            "in": "header",
            "required": false,
            "description": "Your player id: 16 to 64 characters from a-z, 0-9 and \"-\". It holds your seat. No account or key.",
            "schema": {
              "type": "string",
              "pattern": "^[a-z0-9-]{16,64}$"
            }
          }
        ],
        "responses": {
          "200": {
            "description": "The session. In this example, X won the live game, so turn is null.",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/SessionView"
                },
                "example": {
                  "code": "AB3K",
                  "name": "Agent match",
                  "games": [
                    {
                      "moves": [
                        0,
                        1,
                        16,
                        2,
                        32,
                        3,
                        48
                      ],
                      "times": [
                        1791200010000,
                        1791200020000,
                        1791200030000,
                        1791200040000,
                        1791200050000,
                        1791200060000,
                        1791200070000
                      ],
                      "clock": {
                        "perMove": null,
                        "perGame": null
                      },
                      "timedOut": false
                    }
                  ],
                  "seats": {
                    "X": true,
                    "O": true
                  },
                  "you": "X",
                  "options": {
                    "hideBoard": false,
                    "hideHistory": false,
                    "hideCoordinates": false
                  },
                  "locked": false,
                  "clock": {
                    "perMove": null,
                    "perGame": null
                  },
                  "fixedSeats": false,
                  "watcherChat": true,
                  "flipped": [
                    false
                  ],
                  "now": 1791200000000,
                  "version": 9,
                  "chat": [
                    {
                      "id": 1,
                      "from": "O",
                      "text": "Good game!",
                      "at": 1791200075000
                    }
                  ],
                  "presence": {
                    "X": false,
                    "O": false
                  },
                  "players": {
                    "X": null,
                    "O": null
                  },
                  "names": {
                    "X": "braveOtter",
                    "O": "cleverHeron"
                  },
                  "people": {
                    "X": "3f9a0c27d84be615",
                    "O": "b71e4d0a92c3f856"
                  },
                  "watchers": [],
                  "youWatcher": null,
                  "seatRequest": null,
                  "turn": null,
                  "status": {
                    "kind": "won",
                    "winner": "X",
                    "line": [
                      0,
                      16,
                      32,
                      48
                    ]
                  },
                  "playoff": null
                }
              }
            }
          },
          "400": {
            "description": "The code is not 4 letters or digits. Or: wait is not a whole number of 0 or more.",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            }
          },
          "404": {
            "description": "No game has this code.",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            }
          },
          "503": {
            "description": "Too many requests wait now. Try again in a few seconds.",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            }
          }
        }
      },
      "patch": {
        "operationId": "updateSession",
        "tags": [
          "Play"
        ],
        "summary": "Rename a session, or change its options, time limit or seat rotation.",
        "description": "A new time limit starts with the next game. `fixedSeats` decides if X and O swap for each new game. `watcherChat` decides if watchers can write in the chat. During a lock, only the name and `watcherChat` can change.\n\nExample:\n\n```sh\ncurl -s -X PATCH {origin}/api/sessions/AB3K -H 'X-Player: agent-7f3k9q2m4x8w1z5c' -H 'content-type: application/json' -d '{\"name\":\"Rematch\"}'\n```",
        "parameters": [
          {
            "name": "code",
            "in": "path",
            "required": true,
            "description": "The session code: 4 letters or digits. Lower case also works.",
            "schema": {
              "type": "string",
              "pattern": "^[ABCDEFGHJKLMNPQRSTUVWXYZ23456789abcdefghjklmnpqrstuvwxyz23456789]{4}$"
            },
            "example": "AB3K"
          },
          {
            "name": "X-Player",
            "in": "header",
            "required": true,
            "description": "Your player id: 16 to 64 characters from a-z, 0-9 and \"-\". It holds your seat. No account or key.",
            "schema": {
              "type": "string",
              "pattern": "^[a-z0-9-]{16,64}$"
            }
          },
          {
            "$ref": "#/components/parameters/IdempotencyKey"
          }
        ],
        "requestBody": {
          "required": true,
          "content": {
            "application/json": {
              "schema": {
                "$ref": "#/components/schemas/SessionUpdate"
              },
              "example": {
                "name": "Rematch"
              }
            }
          }
        },
        "responses": {
          "200": {
            "description": "The changed session.",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/SessionView"
                },
                "example": {
                  "code": "AB3K",
                  "name": "Rematch",
                  "games": [
                    {
                      "moves": [],
                      "times": [],
                      "clock": {
                        "perMove": null,
                        "perGame": null
                      },
                      "timedOut": false
                    }
                  ],
                  "seats": {
                    "X": true,
                    "O": true
                  },
                  "you": "X",
                  "options": {
                    "hideBoard": false,
                    "hideHistory": false,
                    "hideCoordinates": false
                  },
                  "locked": false,
                  "clock": {
                    "perMove": null,
                    "perGame": null
                  },
                  "fixedSeats": false,
                  "watcherChat": true,
                  "flipped": [
                    false
                  ],
                  "now": 1791200000000,
                  "version": 3,
                  "chat": [],
                  "presence": {
                    "X": false,
                    "O": false
                  },
                  "players": {
                    "X": null,
                    "O": null
                  },
                  "names": {
                    "X": "braveOtter",
                    "O": "cleverHeron"
                  },
                  "people": {
                    "X": "3f9a0c27d84be615",
                    "O": "b71e4d0a92c3f856"
                  },
                  "watchers": [],
                  "youWatcher": null,
                  "seatRequest": null,
                  "turn": "X",
                  "status": {
                    "kind": "playing"
                  },
                  "playoff": null
                }
              }
            }
          },
          "400": {
            "description": "The X-Player header is missing or not 16 to 64 characters from a-z, 0-9 and \"-\", or it starts with \"account-\". Or: The code is not 4 letters or digits. Or: The body is not valid JSON, or a field is wrong. Or: The Idempotency-Key header is not valid.",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            }
          },
          "403": {
            "description": "You hold no seat in this game. Watchers only read.",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            }
          },
          "404": {
            "description": "No game has this code.",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            }
          },
          "409": {
            "description": "The settings are locked until the live game ends. Or: The first request with this Idempotency-Key still runs.",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            }
          },
          "422": {
            "description": "This Idempotency-Key came with another request before.",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            }
          }
        }
      }
    },
    "/api/sessions/{code}/join": {
      "post": {
        "operationId": "joinSession",
        "tags": [
          "Play"
