    "/api/events": {
      "post": {
        "operationId": "reportFault",
        "tags": [
          "Account"
        ],
        "summary": "Report a fault on a page, for the stats page. The page uses it.",
        "description": "At most 1 kB. One address can send 30 reports per 10 minutes.\n\nExample:\n\n```sh\ncurl -s -X POST {origin}/api/events -H 'content-type: application/json' -d '{\"kind\":\"error\",\"message\":\"TypeError: x is undefined (index-B2x9kQ.js:1:200)\",\"version\":\"index-B2x9kQ\"}'\n```",
        "parameters": [],
        "requestBody": {
          "required": true,
          "content": {
            "application/json": {
              "schema": {
                "$ref": "#/components/schemas/ClientEvent"
              },
              "example": {
                "kind": "error",
                "message": "TypeError: x is undefined (index-B2x9kQ.js:1:200)",
                "version": "index-B2x9kQ"
              }
            }
          }
        },
        "responses": {
          "200": {
            "description": "Stored.",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Ok"
                },
                "example": {
                  "ok": true
                }
              }
            }
          },
          "400": {
            "description": "The event needs a kind, a message of 1 to 300 characters and a version.",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            }
          },
          "413": {
            "description": "The body is larger than 1 kB.",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            }
          },
          "429": {
            "description": "This address sent 30 reports in the last 10 minutes.",
            "headers": {
              "Retry-After": {
                "description": "Whole seconds to wait before the next try.",
                "schema": {
                  "type": "integer",
                  "minimum": 1
                }
              }
            },
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            }
          }
        }
      }
    },
    "/api/practice/runs": {
      "post": {
        "operationId": "addPracticeRun",
        "tags": [
          "Account"
        ],
        "summary": "Store a finished practice run of the Voice room (/sound-input). The page uses it.",
        "description": "One address can send 60 runs per 10 minutes. The leaderboards and the stats page count them.\n\nExample:\n\n```sh\ncurl -s -X POST {origin}/api/practice/runs -H 'X-Player: agent-7f3k9q2m4x8w1z5c' -H 'content-type: application/json' -d '{\"id\":\"run-6f1d2c9a\",\"mode\":\"targets\",\"preset\":\"normal\",\"roundMs\":[2100,1850,3020,2400,1990,2760,2210,1580,3300,2040],\"score\":10}'\n```",
