          {
            "name": "X-Player",
            "in": "header",
            "required": true,
            "description": "Your player id: 16 to 64 characters from a-z, 0-9 and \"-\". It holds your seat. No account or key.",
            "schema": {
              "type": "string",
              "pattern": "^[a-z0-9-]{16,64}$"
            }
          }
        ],
        "requestBody": {
          "required": true,
          "content": {
            "application/json": {
              "schema": {
                "$ref": "#/components/schemas/PracticeRun"
              },
              "example": {
                "id": "run-6f1d2c9a",
                "mode": "targets",
                "preset": "normal",
                "roundMs": [
                  2100,
                  1850,
                  3020,
                  2400,
                  1990,
                  2760,
                  2210,
                  1580,
                  3300,
                  2040
                ],
                "score": 10
              }
            }
          }
        },
        "responses": {
          "200": {
            "description": "Stored, or already stored.",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/PracticeStored"
