                  },
                  "seat_metrics": {
                    "deleted": 0,
                    "anonymised": 0
                  },
                  "player_names": {
                    "deleted": 0,
                    "anonymised": 0
                  },
                  "blocks": {
                    "deleted": 0,
                    "anonymised": 0
                  },
                  "private_stats": {
                    "deleted": 0,
                    "anonymised": 0
                  },
                  "achievement_resets": {
                    "deleted": 0,
                    "anonymised": 0
                  },
                  "achievement_players": {
                    "deleted": 0,
                    "anonymised": 0
                  },
                  "seat_people": {
                    "deleted": 0,
                    "anonymised": 0
                  },
                  "practice_runs": {
                    "deleted": 0,
                    "anonymised": 0
                  },
                  "reports": {
                    "deleted": 0,
                    "anonymised": 0
                  },
                  "tester_codes": {
                    "deleted": 0,
