    "/api/nearby/hosts": {
      "get": {
        "operationId": "nearbyHosts",
        "tags": [
          "Nearby"
        ],
        "summary": "The open Nearby games on your network. The page uses it.",
        "description": "The list holds only the games that hosts announced from your network: the same IPv4 address, or the same IPv6 /64 prefix. It never holds your own games (by your X-Player id), and it holds no player ids. To join a game, answer its offer code and send the answer with POST /api/nearby/hosts/{host}/answer. The page reads the list every few seconds.\n\nExample:\n\n```sh\ncurl -s {origin}/api/nearby/hosts -H 'X-Player: agent-b2c8n4v6x1q9w3e7'\n```",
        "parameters": [
          {
            "name": "X-Player",
            "in": "header",
            "required": false,
            "description": "Your player id: 16 to 64 characters from a-z, 0-9 and \"-\". It holds your seat. No account or key.",
            "schema": {
              "type": "string",
              "pattern": "^[a-z0-9-]{16,64}$"
            }
          }
        ],
        "responses": {
          "200": {
            "description": "The games, oldest first. Empty when no host on your network announced a game.",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/NearbyHosts"
                },
                "example": {
                  "hosts": [
                    {
                      "id": "q8Zr2Lx0Vb7Nc4Mw",
                      "name": "Living room laptop",
                      "device": "computer",
                      "age": 42,
                      "offer": "T3A1.BcHRCoIwFADQX4n7PKG5qflYaQmKKUYWIrK0bNnaqDH1pW_vnAoi43WAYCXseMq75XxpXYXlxtcFMQkdAUHB51ubH-i5bPieTVEfmNNVhdl9y4fSSnWomvVj17pGhICAAaoq-AWYfsunTo_CisU06mzwGRsBOZTYGNkYE5942MF1jaAFBAk3_N0vPlKKxYspLRXUfw"
                    }
                  ]
                }
              }
            }
          },
          "400": {
            "description": "The server cannot tell the network of your request.",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            }
          }
        }
      },
      "post": {
        "operationId": "announceNearbyHost",
        "tags": [
          "Nearby"
        ],
        "summary": "Put your open Nearby game in the list of your network, and wait for a guest. The page uses it.",
        "description": "A web page cannot find other devices on a local network, so a host announces its game here. Without an id, the answer comes at once with the id of your game. Send the next request at once, with that id: the server holds it until a guest sends an answer, or for about 25 s. Then send the next one, and so on. Your game stays in the list while a request is open, and for 10 s after one ends. When the request closes early (you left), your game leaves the list at once. An offer takes one answer: after an answer, send a fresh offer. One network can have 10 games in the list, and send 120 announcements and answers per 10 minutes.\n\nExample:\n\n```sh\ncurl -s -X POST {origin}/api/nearby/hosts -H 'X-Player: agent-7f3k9q2m4x8w1z5c' -H 'content-type: application/json' -d '{\"offer\":\"T3A1.BcHRCoIwFADQX4n7PKG5qflYaQmKKUYWIrK0bNnaqDH1pW_vnAoi43WAYCXseMq75XxpXYXlxtcFMQkdAUHB51ubH-i5bPieTVEfmNNVhdl9y4fSSnWomvVj17pGhICAAaoq-AWYfsunTo_CisU06mzwGRsBOZTYGNkYE5942MF1jaAFBAk3_N0vPlKKxYspLRXUfw\",\"id\":\"q8Zr2Lx0Vb7Nc4Mw\"}'\n```",
        "parameters": [
          {
            "name": "X-Player",
            "in": "header",
            "required": true,
            "description": "Your player id: 16 to 64 characters from a-z, 0-9 and \"-\". It holds your seat. No account or key.",
            "schema": {
              "type": "string",
              "pattern": "^[a-z0-9-]{16,64}$"
            }
          }
        ],
        "requestBody": {
          "required": true,
          "content": {
            "application/json": {
              "schema": {
                "$ref": "#/components/schemas/NearbyAnnounce"
              },
              "example": {
                "offer": "T3A1.BcHRCoIwFADQX4n7PKG5qflYaQmKKUYWIrK0bNnaqDH1pW_vnAoi43WAYCXseMq75XxpXYXlxtcFMQkdAUHB51ubH-i5bPieTVEfmNNVhdl9y4fSSnWomvVj17pGhICAAaoq-AWYfsunTo_CisU06mzwGRsBOZTYGNkYE5942MF1jaAFBAk3_N0vPlKKxYspLRXUfw",
                "id": "q8Zr2Lx0Vb7Nc4Mw"
              }
            }
          }
        },
        "responses": {
          "200": {
            "description": "Your game is in the list (without an id), a guest answered, or the wait ended.",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/NearbyAnnounced"
                },
                "example": {
                  "id": "q8Zr2Lx0Vb7Nc4Mw",
                  "answer": "T3B1.BcFdD0JQHAfg7_K7_tucw1EuJbHVvCyrlpkhojJnJdRFn73nSRBNWgXC-SkGt1netg_e-YU-2rPxtV7mBYR9-6nKKNBPx6x189m7rsdDIZ2wttv7UfEHR2ZWsymNsXNAKEFJgl-9Ut-hKovY5UEt-p1nq0o8gYSucUacMc3UFkywNCVIEPw-R_oH"
                }
              }
            }
          },
          "400": {
            "description": "The X-Player header is missing or not 16 to 64 characters from a-z, 0-9 and \"-\", or it starts with \"account-\". Or: The body is not valid JSON, the offer is not a valid offer code, or the server cannot tell the network of your request.",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            }
          },
          "404": {
            "description": "The id is not in the list any more, or it is not yours. Announce again without an id.",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            }
          },
          "413": {
            "description": "The body is larger than 4 kB.",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            }
          },
          "429": {
            "description": "Your network has 10 games in the list, or sent 120 Nearby calls in the last 10 minutes.",
            "headers": {
              "Retry-After": {
                "description": "Whole seconds to wait before the next try.",
                "schema": {
                  "type": "integer",
                  "minimum": 1
                }
              }
            },
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            }
          },
          "503": {
            "description": "Too many games are in the list on this server.",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            }
          }
        }
      }
    },
