      "post": {
        "operationId": "answerNearbyHost",
        "tags": [
          "Nearby"
        ],
        "summary": "Send your answer to the offer of a Nearby host. The page uses it.",
        "description": "The server passes the answer to the open request of the host. The host then connects to you directly over WebRTC. The game leaves the list until the host announces a fresh offer.\n\nExample:\n\n```sh\ncurl -s -X POST {origin}/api/nearby/hosts/q8Zr2Lx0Vb7Nc4Mw/answer -H 'X-Player: agent-b2c8n4v6x1q9w3e7' -H 'content-type: application/json' -d '{\"answer\":\"T3B1.BcFdD0JQHAfg7_K7_tucw1EuJbHVvCyrlpkhojJnJdRFn73nSRBNWgXC-SkGt1netg_e-YU-2rPxtV7mBYR9-6nKKNBPx6x189m7rsdDIZ2wttv7UfEHR2ZWsymNsXNAKEFJgl-9Ut-hKovY5UEt-p1nq0o8gYSucUacMc3UFkywNCVIEPw-R_oH\",\"offer\":\"T3A1.BcHRCoIwFADQX4n7PKG5qflYaQmKKUYWIrK0bNnaqDH1pW_vnAoi43WAYCXseMq75XxpXYXlxtcFMQkdAUHB51ubH-i5bPieTVEfmNNVhdl9y4fSSnWomvVj17pGhICAAaoq-AWYfsunTo_CisU06mzwGRsBOZTYGNkYE5942MF1jaAFBAk3_N0vPlKKxYspLRXUfw\"}'\n```",
        "parameters": [
          {
            "name": "host",
            "in": "path",
            "required": true,
            "description": "The id of a Nearby host, from GET /api/nearby/hosts.",
            "schema": {
              "type": "string",
              "pattern": "^[A-Za-z0-9_-]{16}$"
            },
            "example": "q8Zr2Lx0Vb7Nc4Mw"
          },
          {
            "name": "X-Player",
            "in": "header",
            "required": true,
            "description": "Your player id: 16 to 64 characters from a-z, 0-9 and \"-\". It holds your seat. No account or key.",
            "schema": {
              "type": "string",
              "pattern": "^[a-z0-9-]{16,64}$"
            }
          }
        ],
        "requestBody": {
          "required": true,
          "content": {
            "application/json": {
              "schema": {
                "$ref": "#/components/schemas/NearbyAnswer"
              },
              "example": {
                "answer": "T3B1.BcFdD0JQHAfg7_K7_tucw1EuJbHVvCyrlpkhojJnJdRFn73nSRBNWgXC-SkGt1netg_e-YU-2rPxtV7mBYR9-6nKKNBPx6x189m7rsdDIZ2wttv7UfEHR2ZWsymNsXNAKEFJgl-9Ut-hKovY5UEt-p1nq0o8gYSucUacMc3UFkywNCVIEPw-R_oH",
                "offer": "T3A1.BcHRCoIwFADQX4n7PKG5qflYaQmKKUYWIrK0bNnaqDH1pW_vnAoi43WAYCXseMq75XxpXYXlxtcFMQkdAUHB51ubH-i5bPieTVEfmNNVhdl9y4fSSnWomvVj17pGhICAAaoq-AWYfsunTo_CisU06mzwGRsBOZTYGNkYE5942MF1jaAFBAk3_N0vPlKKxYspLRXUfw"
              }
            }
          }
        },
        "responses": {
          "200": {
            "description": "The answer is on its way to the host.",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Ok"
                },
                "example": {
                  "ok": true
                }
              }
            }
          },
          "400": {
            "description": "The X-Player header is missing or not 16 to 64 characters from a-z, 0-9 and \"-\", or it starts with \"account-\". Or: The host id is not 16 characters, the body is not valid JSON or misses a code, the answer is not a valid answer code, or the server cannot tell the network of your request.",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            }
          },
          "404": {
            "description": "No host on your network has this id.",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            }
          },
          "409": {
            "description": "Another device answered this offer first, or the host has a newer offer. Read the list again in a few seconds.",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            }
          },
          "413": {
            "description": "The body is larger than 4 kB.",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            }
          },
          "429": {
            "description": "Your network sent 120 Nearby calls in the last 10 minutes.",
            "headers": {
              "Retry-After": {
                "description": "Whole seconds to wait before the next try.",
                "schema": {
                  "type": "integer",
                  "minimum": 1
                }
              }
            },
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            }
          }
        }
      }
    }
  },
  "components": {
    "schemas": {
      "Player": {
        "type": "string",
        "enum": [
          "X",
          "O"
        ],
        "description": "A seat. X moves first in every game. The players swap X and O for each new game, unless fixedSeats is true."
      },
      "Cell": {
        "type": "integer",
        "minimum": 0,
        "maximum": 63,
        "description": "layer * 16 + row * 4 + column, each 0 to 3. Layer 0 is the bottom layer."
      },
      "TimeControl": {
        "type": "object",
        "description": "A time limit, like a chess clock. null means no limit of that kind.",
        "properties": {
          "perMove": {
            "type": [
              "integer",
              "null"
            ],
            "minimum": 3,
            "maximum": 600,
            "description": "Seconds for each move."
          },
          "perGame": {
            "type": [
              "integer",
              "null"
            ],
            "minimum": 30,
            "maximum": 7200,
            "description": "Seconds for each player for the whole game."
          }
        },
        "required": [
          "perMove",
          "perGame"
        ],
        "additionalProperties": false
      },
      "GameRecord": {
        "type": "object",
        "description": "One game. The last game in a session is the live game.",
        "properties": {
          "moves": {
            "type": "array",
            "items": {
              "$ref": "#/components/schemas/Cell"
            },
            "maxItems": 64,
            "description": "The cells in move order. X played the even indexes (0, 2, 4...), O the odd ones."
          },
          "times": {
            "type": "array",
            "items": {
              "type": "number"
            },
            "description": "The server time of each move, in epoch milliseconds."
          },
          "clock": {
            "$ref": "#/components/schemas/TimeControl"
          },
          "timedOut": {
            "type": "boolean",
            "description": "True when the player to move ran out of time."
          },
          "abandoned": {
            "const": true,
            "description": "Set when nobody moved for a week, so the server ended the game. It has no winner and no result."
          }
        },
        "required": [
          "moves",
          "times",
          "clock",
          "timedOut"
        ],
        "additionalProperties": false
      },
      "Status": {
        "description": "The state of the live game.",
        "oneOf": [
          {
            "type": "object",
            "description": "The game goes on.",
            "properties": {
              "kind": {
                "const": "playing"
              }
            },
            "required": [
              "kind"
            ],
            "additionalProperties": false
          },
          {
            "type": "object",
            "description": "A player has four in a line.",
            "properties": {
              "kind": {
                "const": "won"
              },
              "winner": {
                "$ref": "#/components/schemas/Player"
              },
              "line": {
                "type": "array",
                "items": {
                  "$ref": "#/components/schemas/Cell"
                },
                "minItems": 4,
                "maxItems": 4,
                "description": "The four winning cells."
              }
            },
            "required": [
              "kind",
              "winner",
              "line"
            ],
            "additionalProperties": false
          },
          {
            "type": "object",
            "description": "The other player ran out of time.",
            "properties": {
              "kind": {
                "const": "timeout"
              },
              "winner": {
                "$ref": "#/components/schemas/Player"
              }
            },
            "required": [
              "kind",
              "winner"
            ],
            "additionalProperties": false
          },
          {
            "type": "object",
            "description": "The cube is full and no player has a line.",
            "properties": {
              "kind": {
                "const": "draw"
              }
            },
            "required": [
