          "avatar": {
            "type": "string",
            "pattern": "^https://avatars\\.githubusercontent\\.com/"
          },
          "url": {
            "type": "string",
            "pattern": "^https://github\\.com/",
            "description": "The GitHub profile."
          }
        },
        "required": [
          "login",
          "avatar",
          "url"
        ],
        "additionalProperties": false
      },
      "Preview": {
        "type": "object",
        "description": "An open pull request with a live preview.",
        "properties": {
          "number": {
            "type": "integer",
            "minimum": 1
          },
          "title": {
            "type": "string"
          },
          "description": {
            "type": "string",
            "maxLength": 280,
            "description": "The first paragraph of the pull request text, without Markdown."
          },
          "url": {
            "type": "string",
            "pattern": "^https://github\\.com/",
            "description": "The pull request on GitHub."
          },
          "previewUrl": {
            "type": "string",
            "pattern": "^https://([a-z0-9-]+-)?pr-[0-9]+\\.",
            "description": "The preview site: https://tick3d-pr-<number>.yarden-zamir.com."
          },
          "updatedAt": {
            "type": "number",
            "description": "The last change of the pull request, in epoch milliseconds."
          },
          "draft": {
            "type": "boolean"
          },
          "contributors": {
            "type": "array",
            "description": "The author of the pull request and the commit authors with a GitHub account, most commits first. No bots.",
            "items": {
              "$ref": "#/components/schemas/Contributor"
            }
          },
          "parent": {
            "oneOf": [
              {
                "type": "integer",
                "minimum": 1
              },
              {
                "type": "null"
              }
            ],
            "description": "A stacked pull request: the number of the listed pull request whose head branch is the base branch of this one. null when it is top level. An older server sends no such field."
          },
          "toy": {
            "type": "boolean",
            "description": "The pull request has the label \"Toys\": its preview also serves a toy at /toys/. An older server sends no such field."
          },
          "images": {
            "type": "array",
            "description": "The images of the pull request text, in their order. An older server sends no such field.",
            "items": {
              "$ref": "#/components/schemas/PreviewImage"
            },
            "maxItems": 8
          }
        },
        "required": [
          "number",
          "title",
          "description",
          "url",
          "previewUrl",
          "updatedAt",
          "draft",
          "contributors"
        ],
        "additionalProperties": false
      },
      "PreviewImage": {
        "type": "object",
        "description": "An image of the pull request text, such as a screenshot of the change.",
        "properties": {
          "src": {
            "type": "string",
            "description": "From GitHub only: https://raw.githubusercontent.com/, https://github.com/user-attachments/assets/, https://user-images.githubusercontent.com/"
          },
          "alt": {
            "type": "string",
            "maxLength": 200,
            "description": "The text of the image. Empty when the text gives none."
          }
        },
        "required": [
          "src",
          "alt"
        ],
        "additionalProperties": false
      },
      "BlockRequest": {
        "type": "object",
        "description": "A block.",
        "properties": {
          "name": {
            "type": "string",
            "minLength": 1,
            "maxLength": 40,
            "description": "The name that you saw, for your list of blocked people."
          }
        },
        "required": [
          "name"
        ],
        "additionalProperties": false
      },
      "Blocks": {
        "type": "object",
        "description": "The people that you blocked, newest first. Their messages and names stay hidden on your devices.",
        "properties": {
          "blocked": {
            "type": "array",
            "description": "The blocked people.",
            "items": {
              "type": "object",
              "description": "A blocked person.",
              "properties": {
                "person": {
                  "type": "string",
                  "pattern": "^[0-9a-f]{16}$",
                  "description": "A public person id. The same player has the same id in every session, also on every device of a GitHub account. It is not a player id and reveals none."
                },
                "name": {
                  "type": "string",
                  "minLength": 1,
                  "maxLength": 40,
                  "description": "A custom name that the player chose, else a generated name."
                },
                "at": {
                  "type": "number",
                  "description": "The time of the block, in epoch milliseconds."
                }
              },
              "required": [
                "person",
                "name",
                "at"
              ],
              "additionalProperties": false
            }
          }
        },
        "required": [
          "blocked"
        ],
        "additionalProperties": false
      },
      "ReportRequest": {
        "type": "object",
        "description": "A report of one chat message or one person. Send `message` or `person`, not both. A message needs `code`. A person without `code` is a player of the stats page.",
        "properties": {
          "code": {
            "type": "string",
            "pattern": "^[ABCDEFGHJKLMNPQRSTUVWXYZ23456789abcdefghjklmnpqrstuvwxyz23456789]{4}$",
            "description": "The session code."
          },
          "message": {
            "type": "integer",
            "minimum": 1,
            "description": "The id of a message in the chat of the session."
          },
          "person": {
            "type": "string",
            "pattern": "^[0-9a-f]{16}$",
            "description": "With `code`, the person id of a player or watcher in the session now. Without it, a person with a finished game or an account."
          },
          "reason": {
            "type": "string",
            "enum": [
              "spam",
              "abuse",
              "name",
              "other"
            ],
            "description": "spam, abuse, name (an inappropriate name) or other."
          },
          "note": {
            "type": "string",
            "maxLength": 200,
            "description": "Optional. At most 200 characters."
          }
        },
        "required": [
          "reason"
        ],
        "additionalProperties": false
      },
      "ReportStored": {
        "type": "object",
        "description": "The report is stored for the maintainers.",
        "properties": {
          "id": {
            "type": "integer",
            "minimum": 1
          }
        },
        "required": [
          "id"
        ],
        "additionalProperties": false
      },
      "Reports": {
        "type": "object",
        "description": "The newest reports and moderation actions. Only the maintainers can read them.",
        "properties": {
          "reports": {
            "type": "array",
            "description": "The newest reports first.",
            "items": {
              "type": "object",
              "description": "A report. The text and the name are copies from the time of the report.",
              "properties": {
                "id": {
                  "type": "integer",
                  "minimum": 1
                },
                "code": {
                  "oneOf": [
                    {
                      "type": "string"
                    },
                    {
                      "type": "null"
                    }
                  ],
                  "description": "The session code. null for a report from the stats page."
                },
                "message": {
                  "oneOf": [
                    {
                      "type": "integer"
                    },
                    {
                      "type": "null"
                    }
                  ]
                },
                "text": {
                  "oneOf": [
                    {
                      "type": "string"
                    },
                    {
                      "type": "null"
                    }
                  ]
                },
                "person": {
                  "oneOf": [
                    {
                      "type": "string",
                      "pattern": "^[0-9a-f]{16}$",
                      "description": "A public person id. The same player has the same id in every session, also on every device of a GitHub account. It is not a player id and reveals none."
                    },
                    {
                      "type": "null"
                    }
                  ]
                },
                "name": {
                  "oneOf": [
                    {
                      "type": "string"
                    },
                    {
                      "type": "null"
                    }
                  ]
                },
                "reason": {
                  "type": "string",
                  "enum": [
                    "spam",
                    "abuse",
                    "name",
                    "other"
                  ]
                },
                "note": {
                  "oneOf": [
                    {
                      "type": "string"
                    },
                    {
                      "type": "null"
                    }
                  ]
                },
                "reporter": {
                  "oneOf": [
                    {
                      "type": "string",
                      "pattern": "^[0-9a-f]{16}$",
                      "description": "The person id of the reporter. Null when the reporter deleted their data."
                    },
                    {
                      "type": "null"
                    }
                  ]
                },
                "reporterLogin": {
                  "oneOf": [
                    {
                      "type": "string"
                    },
                    {
                      "type": "null"
                    }
                  ]
                },
                "at": {
                  "type": "number"
                }
              },
              "required": [
                "id",
                "code",
                "message",
                "text",
                "person",
                "name",
                "reason",
                "note",
                "reporter",
                "reporterLogin",
                "at"
              ],
              "additionalProperties": false
            }
          },
          "actions": {
            "type": "array",
            "description": "The newest moderation actions first: who did what, and when.",
            "items": {
              "type": "object",
              "description": "A moderation action.",
              "properties": {
                "login": {
                  "type": "string"
                },
                "action": {
                  "type": "string",
                  "enum": [
                    "hide-message",
                    "clear-name"
                  ]
                },
                "code": {
                  "oneOf": [
                    {
                      "type": "string"
                    },
                    {
                      "type": "null"
                    }
                  ]
                },
                "message": {
                  "oneOf": [
                    {
                      "type": "integer"
                    },
                    {
                      "type": "null"
                    }
                  ]
                },
                "person": {
                  "oneOf": [
                    {
                      "type": "string",
                      "pattern": "^[0-9a-f]{16}$",
                      "description": "A public person id. The same player has the same id in every session, also on every device of a GitHub account. It is not a player id and reveals none."
                    },
                    {
                      "type": "null"
                    }
                  ]
                },
                "at": {
                  "type": "number"
                }
              },
              "required": [
                "login",
                "action",
                "code",
                "message",
                "person",
                "at"
              ],
              "additionalProperties": false
            }
          }
        },
        "required": [
          "reports",
          "actions"
        ],
        "additionalProperties": false
      },
      "Stores": {
        "type": "object",
        "description": "Where the apps stand in the stores. The server reads the public Google Play listing of the app at start, then every hour.",
        "properties": {
          "play": {
            "type": "string",
            "enum": [
              "testing",
              "live"
            ],
            "description": "testing: only testers get the Android app (the closed test). live: everyone gets it from Google Play."
          }
        },
        "required": [
          "play"
        ],
        "additionalProperties": false
      },
      "TesterCodes": {
        "type": "object",
        "description": "The Google Play promo codes of the Android closed test, in a fixed order. Never a full code or an email.",
        "properties": {
          "codes": {
            "type": "array",
            "description": "Every code, free and claimed.",
            "items": {
              "type": "object",
              "description": "One code.",
              "properties": {
                "id": {
                  "type": "integer",
                  "minimum": 1,
                  "description": "The id to claim the code with."
                },
                "hint": {
                  "type": "string",
                  "minLength": 3,
                  "maxLength": 3,
                  "description": "The first 3 characters of the code."
                },
                "claimed": {
                  "type": "boolean"
                },
                "name": {
                  "oneOf": [
                    {
                      "type": "string",
                      "minLength": 1,
                      "maxLength": 40,
                      "description": "A display name: 1 to 40 letters, digits, spaces or - _ . '. The server trims spaces."
                    },
                    {
                      "type": "null"
                    }
                  ],
                  "description": "The name of the tester who has the code. null for a free code."
                },
                "gravatar": {
                  "oneOf": [
                    {
                      "type": "string",
                      "pattern": "^[0-9a-f]{64}$"
                    },
                    {
                      "type": "null"
                    }
                  ],
                  "description": "The SHA-256 Gravatar hash of the email of the tester, for https://gravatar.com/avatar/<hash>. null for a free code and for a code that the maintainer gave out by hand."
                }
              },
              "required": [
                "id",
                "hint",
                "claimed",
                "name",
                "gravatar"
              ],
              "additionalProperties": false
            }
          }
        },
        "required": [
          "codes"
        ],
        "additionalProperties": false
      },
      "ClaimRequest": {
        "type": "object",
        "description": "The tester who claims the code. The maintainers add the email to the Google Group of the test.",
        "properties": {
          "email": {
            "type": "string",
            "minLength": 3,
            "maxLength": 254,
            "description": "The email of the Google account on the phone. The server trims spaces."
          },
          "name": {
            "type": "string",
            "minLength": 1,
            "maxLength": 40,
            "description": "A display name: 1 to 40 letters, digits, spaces or - _ . '. The server trims spaces."
          },
          "by": {
            "oneOf": [
              {
                "type": "string",
                "pattern": "^[0-9a-f]{16}$",
                "description": "A public person id. The same player has the same id in every session, also on every device of a GitHub account. It is not a player id and reveals none."
              },
              {
                "type": "null"
              }
            ],
            "description": "The person id of the inviter, from the invite link /share?by=<person id>. The claim counts for their invite achievements. Your own person id counts for nobody. Leave it out, or send null, without an invite."
          }
        },
        "required": [
          "email",
          "name"
        ],
        "additionalProperties": false
      },
      "ClaimedCode": {
        "type": "object",
        "description": "The code is yours.",
        "properties": {
          "code": {
            "type": "string",
            "pattern": "^[A-Z0-9]{10,30}$",
            "description": "The full Google Play promo code."
          }
        },
        "required": [
          "code"
        ],
        "additionalProperties": false
      },
      "TesterClaims": {
        "type": "object",
        "description": "The claimed tester codes with the emails, oldest first. Only the maintainers can read them.",
        "properties": {
          "claims": {
            "type": "array",
            "description": "The claims.",
            "items": {
              "type": "object",
              "description": "A claim.",
              "properties": {
                "hint": {
                  "type": "string",
                  "minLength": 3,
                  "maxLength": 3
                },
                "name": {
                  "type": "string",
                  "minLength": 1,
                  "maxLength": 40,
                  "description": "A display name: 1 to 40 letters, digits, spaces or - _ . '. The server trims spaces."
                },
                "email": {
                  "oneOf": [
                    {
                      "type": "string"
                    },
                    {
                      "type": "null"
                    }
                  ],
                  "description": "null for a code that the maintainer gave out by hand."
                },
                "claimedAt": {
                  "type": "number",
                  "description": "Epoch milliseconds."
                },
                "invitedBy": {
                  "oneOf": [
                    {
                      "type": "string",
                      "pattern": "^[0-9a-f]{16}$",
                      "description": "A public person id. The same player has the same id in every session, also on every device of a GitHub account. It is not a player id and reveals none."
                    },
                    {
                      "type": "null"
                    }
                  ],
                  "description": "The person id of the inviter, or null without an invite. Every claim from before the invite links counts as an invite of the maintainer Yarden."
                }
              },
              "required": [
                "hint",
                "name",
                "email",
                "claimedAt",
                "invitedBy"
              ],
              "additionalProperties": false
            }
          }
        },
        "required": [
          "claims"
        ],
        "additionalProperties": false
      },
      "AppOpen": {
        "type": "object",
        "description": "The paid app opened on this device.",
        "properties": {
          "store": {
            "type": "string",
            "enum": [
              "play",
              "apple"
            ],
            "description": "Which store signed the proof."
          },
          "proof": {
            "type": "string",
            "minLength": 1,
            "maxLength": 32768,
            "description": "The Play Integrity token from the native launch activity, or the signed App Store AppTransaction."
          },
          "device": {
            "type": "string",
            "pattern": "^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$",
            "description": "Apple only: AppStore.deviceVerificationID in lower case. The signed deviceVerification hash must match it. One purchase holds at most 5 devices."
          },
          "by": {
            "oneOf": [
              {
                "type": "string",
                "pattern": "^[0-9a-f]{16}$",
                "description": "A public person id. The same player has the same id in every session, also on every device of a GitHub account. It is not a player id and reveals none."
              },
              {
                "type": "null"
              }
            ],
            "description": "The person id of the inviter, from the invite link /share?by=<person id> that this browser opened first, or null."
          }
        },
        "required": [
          "store",
          "proof",
          "by"
        ],
        "additionalProperties": false
      },
      "PurchaseNonce": {
        "type": "object",
        "description": "A one-time purchase challenge.",
        "properties": {
          "nonce": {
            "type": "string"
          }
        },
        "required": [
          "nonce"
        ],
        "additionalProperties": false
      },
      "CopyAnswer": {
        "type": "object",
        "description": "Whether you hold a copy of the paid Android app.",
        "properties": {
          "hasCopy": {
            "type": "boolean",
            "description": "Whether you hold a copy of the paid Android app: this device holds one, or another device that is logged in to your GitHub account. A copy belongs to the account that logged in last on its device."
          }
        },
        "required": [
          "hasCopy"
        ],
        "additionalProperties": false
      },
      "Previews": {
        "type": "object",
        "description": "The production site and the open pull requests with a live preview, most recently updated first.",
        "properties": {
          "main": {
            "oneOf": [
              {
                "type": "string",
                "pattern": "^https://",
                "description": "The production site, built from the main branch. null on a server without previews."
              },
              {
                "type": "null"
              }
            ]
          },
          "previews": {
            "type": "array",
            "description": "The previews.",
            "items": {
              "$ref": "#/components/schemas/Preview"
            }
          },
          "error": {
            "oneOf": [
              {
                "type": "string",
                "description": "Why the list is empty or old, for example when GitHub does not answer."
              },
              {
                "type": "null"
              }
            ]
          }
        },
        "required": [
          "main",
          "previews",
          "error"
        ],
        "additionalProperties": false
      }
    },
    "parameters": {
      "IdempotencyKey": {
        "name": "Idempotency-Key",
        "in": "header",
        "required": false,
        "description": "Optional. A new random key for each change, for example a UUID. Send the same key when you send the request again: the server sends the first answer again and changes nothing. The server keeps a key for 60 minutes, for your player id and this path.",
        "schema": {
          "type": "string",
          "minLength": 1,
          "maxLength": 255
        }
      }
    }
  }
}

fields.metricsOfResults:
CASE WHEN results.device IS NULL THEN NULL ELSE {
    'device': results.device, 'view': results.view, 'layout': results.layout, 'theme': results.theme,
    'input': {'board': results.input_board, 'keypad': results.input_keypad}, 'refused': results.refused,
    'undos': results.undos, 'thinkMs': results.think_ms, 'offline': results.offline, 'version': results.version,
    'nearby': CASE WHEN results.nearby_role IS NULL THEN NULL ELSE {'role': results.nearby_role, 'other': results.nearby_other} END
  } END

fields.metricsOfSeatMetrics:
CASE WHEN sm.device IS NULL THEN NULL ELSE {
    'device': sm.device, 'view': sm.view, 'layout': sm.layout, 'theme': sm.theme,
    'input': {'board': sm.input_board, 'keypad': sm.input_keypad}, 'refused': sm.refused,
    'undos': sm.undos, 'thinkMs': sm.think_ms, 'offline': sm.offline, 'version': sm.version,
    'nearby': CASE WHEN sm.nearby_role IS NULL THEN NULL ELSE {'role': sm.nearby_role, 'other': sm.nearby_other} END
  } END
